    /// <summary>Raised when a product card is clicked (not the Add to Cart button).</summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string>? categories;
    private PagedResult<Product>? searchResult;

    // Filter state
    private List<string> selectedCategories = new();
    private decimal? filterMinPrice;
    private decimal? filterMaxPrice;
    private bool filterInStockOnly;

    // Paging & sorting
    private string currentSort = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;

    // UI state
    private bool isLoading = true;
    private string? errorMessage;

    private int TotalPages => searchResult is null || searchResult.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)searchResult.TotalCount / PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var categoriesTask = categories is null
                ? ProductService.GetCategoriesAsync()
                : Task.FromResult(categories);

            var filter = BuildFilter();
            var searchTask = ProductService.SearchAsync(filter, currentSort, currentPage, PageSize);

            await Task.WhenAll(categoriesTask, searchTask);

            categories = categoriesTask.Result;
            searchResult = searchTask.Result;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private ProductFilter BuildFilter() => new(
        Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
        MinPrice: filterMinPrice,
        MaxPrice: filterMaxPrice,
        InStockOnly: filterInStockOnly
    );

    // ----- Filter helpers -----

    private bool IsCategorySelected(string category) => selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked && !selectedCategories.Contains(category))
            selectedCategories.Add(category);
        else if (!isChecked)
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadDataAsync();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        filterMinPrice = null;
        filterMaxPrice = null;
        filterInStockOnly = false;
        currentPage = 1;
        await LoadDataAsync();
    }

    // ----- Sort -----

    private async Task OnSortChanged()
    {
        currentPage = 1;
        await LoadDataAsync();
    }

    // ----- Pagination -----

    private async Task PreviousPage()
    {
        if (currentPage > 1)
        {
            currentPage--;
            await LoadDataAsync();
        }
    }

    private async Task NextPage()
    {
        if (currentPage < TotalPages)
        {
            currentPage++;
            await LoadDataAsync();
        }
    }

    private async Task GoToPage(int page)
    {
        currentPage = page;
        await LoadDataAsync();
    }

    // ----- Callbacks -----

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder – integrate with a cart service later
        return Task.CompletedTask;
    }

    // ----- Helpers -----

    private string GetShowingLabel()
    {
        if (searchResult is null || searchResult.TotalCount == 0)
            return "No products";

        int start = (searchResult.Page - 1) * searchResult.PageSize + 1;
        int end = Math.Min(start + searchResult.Items.Count - 1, searchResult.TotalCount);
        return $"Showing {start}\u2013{end} of {searchResult.TotalCount} products";
    }

    private async Task RetryLoad() => await LoadDataAsync();
