@page "/catalog"
@using sv_8b0b24abc44e41d1a77878aa0ae57385.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

<div class="catalog-layout">
    @* ===== LEFT SIDEBAR ===== *@
    <aside class="catalog-sidebar">
        <h2>Filters</h2>

        <div class="filter-section">
            <h3>Category</h3>
            @if (categories is not null)
            {
                @foreach (var category in categories)
                {
                    <label class="filter-checkbox">
                        <input type="checkbox"
                               checked="@IsCategorySelected(category)"
                               @onchange="e => ToggleCategory(category, (bool)(e.Value ?? false))" />
                        @category
                    </label>
                }
            }
        </div>

        <div class="filter-section">
            <h3>Price Range</h3>
            <label>
                Min:
                <input type="number" min="0" step="0.01" @bind="filterMinPrice" placeholder="Min" />
            </label>
            <label>
                Max:
                <input type="number" min="0" step="0.01" @bind="filterMaxPrice" placeholder="Max" />
            </label>
        </div>

        <div class="filter-section">
            <label class="filter-checkbox">
                <input type="checkbox" @bind="filterInStockOnly" />
                In Stock Only
            </label>
        </div>

        <div class="filter-actions">
            <button class="btn-apply" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn-clear" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    @* ===== MAIN CONTENT ===== *@
    <main class="catalog-main">
        @if (isLoading)
        {
            <div class="catalog-loading">
                <p>Loading products…</p>
            </div>
        }
        else if (errorMessage is not null)
        {
            <div class="catalog-error">
                <p>@errorMessage</p>
                <button @onclick="RetryLoad">Retry</button>
            </div>
        }
        else if (searchResult is not null)
        {
            @* Toolbar *@
            <div class="catalog-toolbar">
                <div class="sort-control">
                    <label for="sortSelect">Sort by:</label>
                    <select id="sortSelect" @bind="currentSort" @bind:after="OnSortChanged">
                        <option value="price_asc">Price: Low to High</option>
                        <option value="price_desc">Price: High to Low</option>
                        <option value="name_asc">Name: A-Z</option>
                        <option value="rating_desc">Rating: Highest</option>
                    </select>
                </div>
                <span class="showing-label">
                    @GetShowingLabel()
                </span>
            </div>

            @if (searchResult.Items.Count == 0)
            {
                <div class="catalog-empty">
                    <p>No products match your filters.</p>
                </div>
            }
            else
            {
                @* Product Grid *@
                <div class="product-grid">
                    @foreach (var product in searchResult.Items)
                    {
                        <ProductCard Product="product"
                                     OnProductSelected="HandleProductSelected"
                                     OnAddToCart="HandleAddToCart" />
                    }
                </div>

                @* Pagination *@
                <nav class="pagination" aria-label="Product pagination">
                    <button disabled="@(currentPage <= 1)" @onclick="PreviousPage">Previous</button>
                    @for (int i = 1; i <= TotalPages; i++)
                    {
                        var pageNum = i;
                        <button class="@(pageNum == currentPage ? "page-active" : "")"
                                @onclick="() => GoToPage(pageNum)">
                            @pageNum
                        </button>
                    }
                    <button disabled="@(currentPage >= TotalPages)" @onclick="NextPage">Next</button>
                </nav>
            }
        }
    </main>
</div>

@code {
    /// <summary>Raised when a product card is clicked (not the Add to Cart button).</summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string>? categories;
    private PagedResult<Product>? searchResult;

    // Filter state
    private List<string> selectedCategories = new();
    private decimal? filterMinPrice;
    private decimal? filterMaxPrice;
    private bool filterInStockOnly;

    // Paging & sorting
    private string currentSort = "price_asc";
    private int currentPage = 1;
    private const int PageSize = 12;

    // UI state
    private bool isLoading = true;
    private string? errorMessage;

    private int TotalPages => searchResult is null || searchResult.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)searchResult.TotalCount / PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        isLoading = true;
        errorMessage = null;

        try
        {
            var categoriesTask = categories is null
                ? ProductService.GetCategoriesAsync()
                : Task.FromResult(categories);

            var filter = BuildFilter();
            var searchTask = ProductService.SearchAsync(filter, currentSort, currentPage, PageSize);

            await Task.WhenAll(categoriesTask, searchTask);

            categories = categoriesTask.Result;
            searchResult = searchTask.Result;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load products: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private ProductFilter BuildFilter() => new(
        Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
        MinPrice: filterMinPrice,
        MaxPrice: filterMaxPrice,
        InStockOnly: filterInStockOnly
    );

    // ----- Filter helpers -----

    private bool IsCategorySelected(string category) => selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked && !selectedCategories.Contains(category))
            selectedCategories.Add(category);
        else if (!isChecked)
            selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        currentPage = 1;
        await LoadDataAsync();
    }

    private async Task ClearFilters()
    {
        selectedCategories.Clear();
        filterMinPrice = null;
        filterMaxPrice = null;
        filterInStockOnly = false;
        currentPage = 1;
        await LoadDataAsync();
    }

    // ----- Sort -----

    private async Task OnSortChanged()
    {
        currentPage = 1;
        await LoadDataAsync();
    }

    // ----- Pagination -----

    private async Task PreviousPage()
    {
        if (currentPage > 1)
        {
            currentPage--;
            await LoadDataAsync();
        }
    }

    private async Task NextPage()
    {
        if (currentPage < TotalPages)
        {
            currentPage++;
            await LoadDataAsync();
        }
    }

    private async Task GoToPage(int page)
    {
        currentPage = page;
        await LoadDataAsync();
    }

    // ----- Callbacks -----

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder – integrate with a cart service later
        return Task.CompletedTask;
    }

    // ----- Helpers -----

    private string GetShowingLabel()
    {
        if (searchResult is null || searchResult.TotalCount == 0)
            return "No products";

        int start = (searchResult.Page - 1) * searchResult.PageSize + 1;
        int end = Math.Min(start + searchResult.Items.Count - 1, searchResult.TotalCount);
        return $"Showing {start}\u2013{end} of {searchResult.TotalCount} products";
    }

    private async Task RetryLoad() => await LoadDataAsync();
}

