+    display: flex;
+    flex-direction: column;
+    gap: 0.35rem;
+    flex: 1;
+}
+
+.product-name {
+    font-size: 1rem;
+    margin: 0;
+    overflow: hidden;
+    text-overflow: ellipsis;
+    white-space: nowrap;
+}
+
+.product-price {
+    font-weight: 600;
+    color: #0d6efd;
+    margin: 0;
+}
+
+.product-rating {
+    color: #f5a623;
+    font-size: 1.1rem;
+    letter-spacing: 1px;
+}
+
+.badge-out-of-stock {
+    display: inline-block;
+    background-color: #dc3545;
+    color: #fff;
+    font-size: 0.75rem;
+    padding: 0.15rem 0.5rem;
+    border-radius: 4px;
+    align-self: flex-start;
+}
+
+.btn-add-to-cart {
+    margin-top: auto;
+    padding: 0.45rem;
+    background-color: #198754;
+    color: #fff;
+    border: none;
+    border-radius: 4px;
+    cursor: pointer;
+    font-size: 0.85rem;
+}
+
+.btn-add-to-cart:hover:not(:disabled) {
+    background-color: #157347;
+}
+
+.btn-add-to-cart:disabled {
+    background-color: #adb5bd;
+    cursor: not-allowed;
+}
