+    private async Task GoToPage(int page)
+    {
+        currentPage = page;
+        await LoadDataAsync();
+    }
+
+    private async Task HandleProductSelected(Product product)
+    {
+        await OnProductSelected.InvokeAsync(product);
+    }
+
+    private Task HandleAddToCart(Product product)
+    {
+        return Task.CompletedTask;
+    }
+
+    private string GetShowingLabel()
+    {
+        if (searchResult is null || searchResult.TotalCount == 0)
+            return "No products";
+
+        int start = (searchResult.Page - 1) * searchResult.PageSize + 1;
+        int end = Math.Min(start + searchResult.Items.Count - 1, searchResult.TotalCount);
+        return $"Showing {start}\u2013{end} of {searchResult.TotalCount} products";
+    }
+
+    private async Task RetryLoad() => await LoadDataAsync();
+}
+

toolArgs.file_text:
/* ===== Layout ===== */
.catalog-layout {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

.catalog-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
    border-right: 1px solid #e0e0e0;
    padding-right: 1.5rem;
}

.catalog-main {
    flex: 1;
    min-width: 0;
}

/* ===== Sidebar ===== */
.catalog-sidebar h2 {
    margin-top: 0;
    font-size: 1.25rem;
}

.filter-section {
    margin-bottom: 1.25rem;
}

.filter-section h3 {
    font-size: 1rem;
    margin-bottom: 0.5rem;
}

.filter-checkbox {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    margin-bottom: 0.35rem;
    cursor: pointer;
}

.filter-section input[type="number"] {
    width: 100%;
    padding: 0.35rem;
    margin-top: 0.25rem;
    box-sizing: border-box;
}

.filter-actions {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.btn-apply,
.btn-clear {
    padding: 0.5rem 1rem;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
}

.btn-apply {
    background-color: #0d6efd;
    color: #fff;
}

.btn-apply:hover {
    background-color: #0a58ca;
}

.btn-clear {
    background-color: #6c757d;
    color: #fff;
}

.btn-clear:hover {
    background-color: #565e64;
}

/* ===== Toolbar ===== */
.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.sort-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.sort-control select {
    padding: 0.35rem;
}

.showing-label {
    color: #666;
    font-size: 0.9rem;
}

/* ===== Product Grid ===== */
.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

/* ===== States ===== */
.catalog-loading,
.catalog-error,
.catalog-empty {
    text-align: center;
    padding: 3rem 1rem;
    color: #666;
}

.catalog-error {
    color: #dc3545;
}

.catalog-error button {
    margin-top: 0.75rem;
    padding: 0.4rem 1rem;
    background-color: #0d6efd;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

/* ===== Pagination ===== */
.pagination {
    display: flex;
    justify-content: center;
    gap: 0.35rem;
    margin-top: 1.5rem;
    flex-wrap: wrap;
}

.pagination button {
    padding: 0.4rem 0.75rem;
    border: 1px solid #dee2e6;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
}

.pagination button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.pagination button.page-active {
    background-color: #0d6efd;
    color: #fff;
    border-color: #0d6efd;
}

